#include "stdafx.h"#include "H_Class.h"static SBlockCreate AIREF( "AIREF", SH_AIREF::Create );#include <HPARM_INIT.h> #include "ParmVarInfo.h"LIST_PARM(SH_AIREF,W_AIREF,57)SH_AIREF::SH_AIREF() : pIO( NULL ){}void SH_AIREF::InitParm(){#include "Blocks/AIREF.h"   s_defFlag = SVarInfo::efParam;#include "Blocks/AIREF_P.h"  qsort ( VarInfo, kVarInfo, sizeof ( SVarInfo ), CompVarInfo );}class AIREF_IMPL : public W_AIREF{public:  void StepT( SStepCalcParams &dt, double *pIO, double *pHDY );};void SH_AIREF::StepT( SStepCalcParams &dt ){  __super::StepT( dt );  AIREF_IMPL *impl = reinterpret_cast<AIREF_IMPL*>(W);  impl->StepT( dt, pIO, pHDY );}static LPCSTR s_ConPoint = "PV";static LPCSTR s_HDYtry = "HDYNVAL[0]";//HDYNVAL[1] = PV, HDYNVAL[2] = SV, HDYNVAL[3] = TV, HDYNVAL[4] = QVLPCSTR SH_AIREF::SetDestIO( KBmBase *dest, LPCSTR pszField ){  if( this==dest )    return s_ConPoint;  eVarType type = evtHZ;  BYTE *pV = NULL;  bool b = dest->GetVar( pszField ? pszField : s_ConPoint, &pV, &type );  ASS( b );  ASS( type==evtDouble );  pIO = (double*)pV;  W->PTEXECST = W->PTEXECST.Active;  bool d = dest->GetVar( s_HDYtry, &pV, &type );  if ( d )    pHDY = (double*)pV;  return s_ConPoint;}//////////////////////////////////////////////////////////////////////////void AIREF_IMPL::StepT( SStepCalcParams &dt, double *pIO, double *pHDY ){  if( PVSOURCE.AUTO==PVSOURCE.V )  {    if( pIO )    {      PV = *pIO;      if ( pHDY )      {        for ( int i=0; i<5; ++i )          HDYNVAL[i] = pHDY[i];      }      PVSTS = PVSTS.NORMAL;      BADPVFL = false;    }    else    {      PVSTS = PVSTS.BAD;      BADPVFL = true;    }  }  else if( PVSOURCE.MAN==PVSOURCE.V )  {    PVSTS = PVSTS.MANUAL;    BADPVFL = false;  }}